// A simple resource class
class Widget {};

// Demonstrates the WRONG way: creating multiple control blocks
void createMultipleControlBlocks() {
    Widget* raw_ptr = new Widget();

    // spw1 creates the first control block for raw_ptr
    std::shared_ptr<Widget> spw1(raw_ptr);

    // DANGEROUS: spw2 creates a second, independent control block for the same raw_ptr
    // This will lead to a double-deletion of raw_ptr
    std::shared_ptr<Widget> spw2(raw_ptr); // UB!

    // At scope exit, spw2's ref count goes to 0, deleting raw_ptr.
    // Then spw1's ref count goes to 0, deleting raw_ptr again. Crash!
}

// Demonstrates the RIGHT way: sharing one control block
void shareOneControlBlock() {
    // The first shared_ptr takes ownership of the raw pointer
    std::shared_ptr<Widget> spw1(new Widget());

    // CORRECT: spw2 is created from an existing shared_ptr.
    // It copies the pointer to the control block and increments the ref count.
    std::shared_ptr<Widget> spw2 = spw1;

    // Both spw1 and spw2 now share ownership of the same Widget
    // through the same control block. Ref count is 2.
}
